"use strict";const s=require("../utils/http.js");exports.addAddressAPI=t=>s.http({method:"POST",url:"/user/address",data:t}),exports.deleteAddressAPI=t=>s.http({method:"DELETE",url:`/user/address/${t}`}),exports.getAddressListAPI=()=>s.http({method:"GET",url:"/user/address/list"}),exports.updateAddressAPI=t=>s.http({method:"PUT",url:"/user/address",data:t}),exports.updateDefaultAddressAPI=t=>s.http({method:"PUT",url:"/user/address/default",data:t});
